  Object.keys(b.data.accounts||{}).forEach(function(k){var a=b.data.accounts[k]||{},company=clean(a.profile&&a.profile.name)||k;arr(a.quotes).forEach(function(q){if(q)out.push(normalizeQuote(q,company,'local',k+'|'+String(q.id||id('q')),'Local CRM',k))})});
  return out
